import {MfeInitializationError, initializeMfe} from '../initialize-mfe';
import {loadComponent} from '../load-component';

jest.mock('../load-component');

const loadComponentMock = <jest.Mock<typeof loadComponent>>loadComponent;

describe('initialize-mfe tests', () => {

    describe('when things go well', () => {

        let mockInitFunction: jest.Mock<any, any, any>;
        const mockReturnValue = {
          unloadMfe: (): void => {
            //no-op
          }
        };

        beforeEach(() => {
            mockInitFunction = jest.fn().mockReturnValue(mockReturnValue);
            const mfeModule = {
                default: {
                    psMfeInit: mockInitFunction,
                },
            };
            const loader = (): Promise<typeof mfeModule> => {
                return Promise.resolve(mfeModule);
            };
            loadComponentMock.mockReturnValue(loader);
        });

        it('should call the MFE\'s init function', async () => {
            const response = await initializeMfe({
                element: document.getElementById('foo'),
                locale: 'en_us',
                remote: 'my_mfe_name',
                module: './main-module',
                url: 'https://example.com/remoteEntry.js',
            });

            expect(response).toBe(mockReturnValue);

            expect(mockInitFunction.mock.calls).toHaveLength(1);
        });

        it('should pass the locale to the MFE\'s init function', async () => {
            await initializeMfe({
                element: document.getElementById('foo'),
                locale: 'en_us',
                remote: 'my_mfe_name',
                module: './main-module',
                url: 'https://example.com/remoteEntry.js',
            });

            const config = mockInitFunction.mock.calls[0][0];
            expect(config.locale).toEqual('en_us');
        });

        it('should pass the element to the MFE\'s init function', async () => {
            const element = document.getElementById('foo');

            await initializeMfe({
                element,
                locale: 'en_us',
                remote: 'my_mfe_name',
                module: './main-module',
                url: 'https://example.com/remoteEntry.js',
            });

            const config = mockInitFunction.mock.calls[0][0];
            expect(config.element).toBe(element);
        });

    });

    describe('when things go wrong', () => {

        const loadMfe = (): Promise<void> => {
            return initializeMfe({
                element: document.getElementById('foo'),
                locale: 'en_us',
                remote: 'my_mfe_name',
                module: './main-module',
                url: 'https://example.com/remoteEntry.js',
            });
        };

        it('should detect when a Module Federation error happens', async () => {
            loadComponentMock.mockImplementation((...args) => {
                throw new Error('Boom');
            });

            try {
                await loadMfe();
            }
            catch (error) {
                expect(error.message).toEqual(MfeInitializationError.messages.MODULE_FEDERATION_ERROR);
                expect(error.sourceError.message).toEqual('Boom');
            }
        });

        it('should detect when the module is missing the default export', async () => {
            const mfeModule = {};
            const loader = (): Promise<typeof mfeModule> => {
                return Promise.resolve(mfeModule);
            };
            loadComponentMock.mockReturnValue(loader);

            try {
                await loadMfe();
            }
            catch (error) {
                expect(error.message).toEqual(MfeInitializationError.messages.DEFAULT_MISSING);
                expect(error.sourceError).toBeUndefined();
            }
        });

        it('should detect when the init function is missing', async () => {
            const mfeModule = {
                default: {},
            };
            const loader = (): Promise<typeof mfeModule> => {
                return Promise.resolve(mfeModule);
            };
            loadComponentMock.mockReturnValue(loader);

            try {
                await loadMfe();
            }
            catch (error) {
                expect(error.message).toEqual(MfeInitializationError.messages.INIT_FUNCTION_MISSING);
                expect(error.sourceError).toBeUndefined();
            }
        });

        it('should detect when the init function throws an error', async () => {
            const mockInitFunction = jest.fn(() => {
                throw new Error('Init Function Goes Boom!');
            });
            const mfeModule = {
                default: {
                    psMfeInit: mockInitFunction,
                },
            };
            const loader = (): Promise<typeof mfeModule> => {
                return Promise.resolve(mfeModule);
            };
            loadComponentMock.mockReturnValue(loader);

            try {
                await loadMfe();
            }
            catch (error) {
                expect(error.message).toEqual(MfeInitializationError.messages.INIT_ERROR);
                expect(error.sourceError.message).toEqual('Init Function Goes Boom!');
            }
        });

    });

});
